from collections import Counter
# Re-verify the working f against both demos to confirm.
def comps_of(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; st.append((x,y))
                out.append({'c':c,'cells':set(comp),'r0':min(p[0] for p in comp),'r1':max(p[0] for p in comp),'c0':min(p[1] for p in comp),'c1':max(p[1] for p in comp)})
    return out
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=max(cnt,key=lambda c:cnt[c])
    cs=comps_of(g,bg); out=[r[:] for r in g]
    for cc in cs:
        if len(cc['cells'])>1: continue
        i,j=list(cc['cells'])[0]
        cand=[]
        for other in cs:
            if other is cc: continue
            if other['r0']<=i<=other['r1'] and other['c0']<=j<=other['c1']: cand.append(other['c'])
        if cand:
            best=max(cand,key=lambda C:max(len(o['cells']) for o in cs if o is not cc and o['c']==C))
            out[i][j]=best
        else:
            out[i][j]=bg
    return out
